window.DICTIONARY_ENTRY_SHARDS["0061-0065"]={"0061-0065:b28166bcc7864f":{"word":"Aerobiologie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ae·ro·bio·lo·gie","de-DE":"Ae·ro·bio·lo·gie"},"forms":[{"form":"Aerobiologie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Teildisziplin der Biologie, die sich mit der Erforschung lebender Organismen und biologischer Partikel in der Atmosphäre befasst"}],"synonyms":[],"origins":["[1] Komposition aus dem griechischen Bestimmungswort Aero (Luft…) + Nomen Biologie"],"examples":[{"text":"Die Aerobiologie untersucht Partikel mit biologischem Ursprung, die in der Atmosphäre zu finden sind – Pollen, Pilzsporen, Bakterien und andere – ihre Quellen, ihre Ausbreitung und ihre Auswirkungen.","reference":"Pressemitteilung des 8. Internationalen Kongresses für Aerobiologie, Neuchâtel, 21-25. August 2006"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerobiologie","id":"b28166bcc7864f"},"0061-0065:82290de05f9cf6":{"word":"aengl.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"aengl.","de-DE":"aengl."},"forms":[],"senses":[{"definition":"altenglisch"}],"synonyms":[],"origins":[],"examples":[{"text":"aengl. Sprache","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"aengl.","id":"82290de05f9cf6"},"0061-0065:ac077dab4c7db7":{"word":"aerob","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ae·rob","de-DE":"ae·rob"},"forms":[{"form":"aerob","tags":["Positiv"]},{"form":"aerobe","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"aerobem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"aeroben","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"aerober","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"aerobes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist aerob","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist aerob","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist aerob","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind aerob","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"Sauerstoff zum Leben benötigend, brauchend"}],"synonyms":["mit Sauerstoff"],"origins":["von griechisch: αηρ (aēr) - Luft (vergleiche englisch air)"],"examples":[{"text":"Zelluläre Atmung ist ein aerober Prozess.","reference":""},{"text":"Der Mensch ist ein aerobes Lebewesen.","reference":""}],"idioms":[],"collocations":[],"derivations":["Aerobier","Aerobiose","anaerob","Anaerobier"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"aerob","id":"ac077dab4c7db7"},"0061-0065:295991fef32e55":{"word":"Aerogel","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ae·ro·gel","de-DE":"Ae·ro·gel"},"forms":[{"form":"Aerogel","tags":["Nominativ","Singular"]},{"form":"Aerogele","tags":["Nominativ","Plural"]},{"form":"Aerogels","tags":["Genitiv","Singular"]},{"form":"Aerogelen","tags":["Dativ","Plural"]}],"senses":[{"definition":"hochporöser Festkörper, bei dem bis zu 95 % des Volumens aus Poren bestehen"}],"synonyms":[],"origins":["[1] Kompositum aus dem gebundenen Lexem aero- (Luft) und dem Substantiv Gel (weder flüssige noch fest): Gel, das einen hohen Luftanteil besitzt"],"examples":[{"text":"Aerogel ist in der Lage, eine Last von mehr als dem 2000fachen seines Eigengewichtes zu tragen, ohne zu kollabieren.","reference":""},{"text":"„Aerogele halten 14 Einträge im Guinness-Buch der Rekorde für Materialeigenschaften, inklusive ‚bester Isolator‘ und ‚leichtester Feststoff‘.“","reference":"Wikipedia-Artikel „Aerogel“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerogel","id":"295991fef32e55"},"0061-0065:9b7c31871b59b2":{"word":"AEG","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"AEG","de-DE":"AEG"},"forms":[],"senses":[{"definition":"Allgemeines Eisenbahngesetz"}],"synonyms":["Allgemeine Elektricitäts-Gesellschaft","DEG","Deutsche Edison-Gesellschaft"],"origins":[],"examples":[{"text":"Gemäß § 1 AEG dient das Allgemeine Eisenbahngesetz der Gewährleistung eines sicheren Betriebs der Eisenbahn und eines attraktiven Verkehrsangebotes auf der Schiene sowie der Wahrung der Interessen der Verbraucher im Eisenbahnmarkt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"AEG","id":"9b7c31871b59b2"},"0061-0065:95387a68e43e94":{"word":"AELV","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"AELV","de-DE":"AELV"},"forms":[],"senses":[{"definition":"Abkürzung für Arbeitseinkommen-von-Landwirten-Verordnung"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Arbeitseinkommenverordnung Landwirtschaft 2010 - AELV 2010 wurde am 21.09.2009 ausgefertigt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"AELV","id":"95387a68e43e94"},"0061-0065:820b83420d24db":{"word":"AEntG","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"AEntG","de-DE":"AEntG"},"forms":[],"senses":[{"definition":"Abkürzung für Arbeitnehmerentsendegesetz"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"AEntG","id":"820b83420d24db"},"0061-0065:b7be65f121b22e":{"word":"ae.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"ae.","de-DE":"ae."},"forms":[{"form":"aengl.","tags":["variant"]}],"senses":[{"definition":"altenglisch"}],"synonyms":[],"origins":[],"examples":[{"text":"ae. Gedichte","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ae.","id":"b7be65f121b22e"},"0061-0065:91fafb127c0e82":{"word":"Aerobic","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ae·ro·bic","de-DE":"Ae·ro·bic"},"forms":[{"form":"Aerobic","tags":["Nominativ","Singular"]},{"form":"Aerobics","tags":["variant"]}],"senses":[{"definition":"Fitnesstraining, bei dem meist in Begleitung von Musik die beiden Sportarten Gymnastik und Tanz mit dem Ziel verbunden werden, den Umsatz von Sauerstoff im Körper zu verstärken"}],"synonyms":[],"origins":["[1] vom englisch-amerikanischen aerobics ^(→ en), Plural zu „aerobic ^(→ en)“ „unter Einfluss von Sauerstoff stattfindend“ entlehnt"],"examples":[{"text":"Aerobic ist ein Fitnesstraining für den menschlichen Körper und stärkt die Lunge und das Herz.","reference":""},{"text":"Zweimal die Woche gehe ich ins Fitnessstudio und mache Aerobic.","reference":""}],"idioms":[],"collocations":[],"derivations":["Aerobic-Studio","Aerobic-Training"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerobic","id":"91fafb127c0e82"},"0061-0065:a884221ec04fb7":{"word":"Aerophagie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Aero·pha·gie","de-DE":"Aero·pha·gie"},"forms":[{"form":"Aerophagie","tags":["Nominativ","Singular"]},{"form":"Aerophagien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"krankhaftes Luftschlucken"}],"synonyms":["Luftschlucken"],"origins":["[1] von griechisch ἀήρ (aēr^☆) ^(→ grc) ‚Luft‘, und dem gebundenen Lexem -phagie von φαγεῖν (phagein^☆) ^(→ grc) „essen“"],"examples":[{"text":"Aerophagie gilt als Symptom für zugrundeliegende Störungen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Aerophagie","id":"a884221ec04fb7"},"0061-0065:3e56e8bc2c4322":{"word":"aerodynamisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ae·ro·dy·na·misch","de-DE":"ae·ro·dy·na·misch"},"forms":[{"form":"aerodynamisch","tags":["Positiv"]},{"form":"aerodynamische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"aerodynamischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"aerodynamischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"aerodynamischer","tags":["Komparativ"]},{"form":"aerodynamisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"aerodynamischere","tags":["Komparativ","Nominativ","strong","Singular","feminine"]},{"form":"aerodynamischste","tags":["Superlativ","Nominativ","strong","Singular","feminine"]},{"form":"aerodynamischerem","tags":["Komparativ","Dativ","strong","Singular","masculine"]},{"form":"aerodynamischeren","tags":["Komparativ","Genitiv","strong","Singular","masculine"]},{"form":"aerodynamischerer","tags":["Komparativ","Nominativ","strong","Singular","masculine"]},{"form":"aerodynamischeres","tags":["Komparativ","Nominativ","strong","Singular","neuter"]},{"form":"aerodynamischstem","tags":["Superlativ","Dativ","strong","Singular","masculine"]},{"form":"aerodynamischsten","tags":["Superlativ","Genitiv","strong","Singular","masculine"]},{"form":"aerodynamischster","tags":["Superlativ","Nominativ","strong","Singular","masculine"]},{"form":"aerodynamischstes","tags":["Superlativ","Nominativ","strong","Singular","neuter"]},{"form":"am aerodynamischsten","tags":["Superlativ"]},{"form":"er ist aerodynamisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist aerodynamisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist aerodynamisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"er ist aerodynamischer","tags":["Komparativ","predicative","Singular","masculine"]},{"form":"es ist aerodynamischer","tags":["Komparativ","predicative","Singular","neuter"]},{"form":"sie sind aerodynamisch","tags":["Positiv","predicative","Plural"]},{"form":"sie ist aerodynamischer","tags":["Komparativ","predicative","Singular","feminine"]},{"form":"sie sind aerodynamischer","tags":["Komparativ","predicative","Plural"]},{"form":"er ist am aerodynamischsten","tags":["Superlativ","predicative","Singular","masculine"]},{"form":"es ist am aerodynamischsten","tags":["Superlativ","predicative","Singular","neuter"]},{"form":"sie ist am aerodynamischsten","tags":["Superlativ","predicative","Singular","feminine"]},{"form":"sie sind am aerodynamischsten","tags":["Superlativ","predicative","Plural"]}],"senses":[{"definition":"eine Form aufweisend, die gegenüber einem umströmenden, gasförmigen Medium (z. B. Luft) nur einen geringen Strömungswiderstand erzeugt"}],"synonyms":["stromlinienförmig","windschlüpfig","windschlüpfrig","windschnittig"],"origins":["aus dem Altgriechischen: ἀήρ (aēr^☆) ^(→ grc) bedeutet Luft und δύναμις (dynamis^☆) ^(→ grc) Kraft"],"examples":[{"text":"Für ein Auto, das schnell sein soll, ist es wichtig, dass es eine aerodynamische Form hat.","reference":""},{"text":"„Seine aerodynamischen Erkenntnisse aus dem Studium des Windes und der Vogelflügel waren die Grundlage für den modernen Segelflug.“","reference":"Janine Ludwig: Geschichte des Fliegens. Berliner Zeitung, Berlin 17.12.2003"},{"text":"[Fahrradrennen:] „Die aerodynamischen Verbesserungen an Rad, Kleidung und Position führen dazu, dass die Fahrer bei gleichen Geschwindigkeiten weniger Kraft aufwenden müssen als etwa vor zehn Jahren.“","reference":"Tom Mustroph: Warum die Tour de France immer schneller wird. In: Zeit Online. 2025-07-18, ISSN 0044-2070 (URL, abgerufen am 21. Juli 2025) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"aerodynamisch","id":"3e56e8bc2c4322"},"0061-0065:295aed0a308abf":{"word":"AED","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"AED","de-DE":"AED"},"forms":[],"senses":[{"definition":"automatisierter externer Defibrillator"}],"synonyms":["automatisierter externer Defibrillator","Laiendefi","Laiendefibrillator"],"origins":[],"examples":[{"text":"In vielen Münchner U-Bahnhöfen gibt es schon einen AED, der über Notruf freizuschalten ist.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"AED","id":"295aed0a308abf"},"0061-0065:667ae3e625f98c":{"word":"Aerophobie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Aero·pho·bie","de-DE":"Aero·pho·bie"},"forms":[{"form":"Aerophobie","tags":["Nominativ","Singular"]},{"form":"Aerophobien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"krankhafte, mithin unbegründete und anhaltende Angst, Luft zu schlucken oder schädliche Gase einzuatmen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Bei der häufigeren enzephalitischen Form der Tollwut kommt es zu Funktionsausfällen mit wechselnden Bewusstseinsstörungen, Hydrophobie, Aerophobie, Aggression, Spasmen und Überfunktion des limbischen Systems (Speichelfluss).“","reference":"Hans W. Doerr, Wolfram H. Gerlich (Hrsg.): Medizinische Virologie. Grundlagen, Diagnostik, Prävention und Therapie viraler Erkrankungen. 2. Auflage. Georg Thieme Verlag, Stuttgart 2010. ISBN 978-3131139627. Seite 50"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerophobie","id":"667ae3e625f98c"},"0061-0065:15093768e4b0a0":{"word":"AE","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"AE","de-DE":"AE"},"forms":[],"senses":[{"definition":"Astronomische Einheit"},{"definition":"amerikanisches Englisch, die englischen US-Dialekte"},{"definition":"Abkürzung für Auftragseingang, eine wirtschaftliche Messgröße"},{"definition":"Umlaut des Buchstabens Ä"},{"definition":"Transliteration des Buchstabens Æ"},{"definition":"AE-Provision, Agenturprovision"},{"definition":"Adobe After Effects"},{"definition":"Aeneon"},{"definition":"Alkoholembryopathie"},{"definition":"Allerhöchster Erlass, Allerhöchste Entscheidung"},{"definition":"Anwendungsentwicklung"},{"definition":"Appendektomie"},{"definition":"Aufenthaltsermittlung, Personenfahndung in Deutschland"},{"definition":"Aufwandsentschädigung, Vergütung"},{"definition":"Ausfuhrerklärung"},{"definition":"Austria Email AG"},{"definition":"L’Année épigraphique, epigrafische Publikation"},{"definition":"Automatic Exposure, Belichtungsautomatik"},{"definition":"Chevrolet AE, Automodell"},{"definition":"Renault AE, Lastwagenmodell"},{"definition":"Elektrophile Addition"},{"definition":"Air Ceylon, sri-lankische Fluggesellschaft"},{"definition":"Iceland Express, isländische Fluggesellschaft"},{"definition":"Mandarin Airlines, taiwanesische Fluggesellschaft"},{"definition":"Vereinigte Arabische Emirate"},{"definition":"verwaltungsgerichtliches Aktenzeichen für Eilverfahren in Asylsachen"},{"definition":"Kraftfahrzeugkennzeichen für Vogtlandkreis, Auerbach/Vogtl"},{"definition":"Kfz-Kennzeichen, Griechenland: Lasithi, freigehalten"},{"definition":"Kfz-Kennzeichen, Großbritannien: Peterborough"},{"definition":"Kfz-Kennzeichen, Niederlande: Oldtimer-Pkw"},{"definition":"Kfz-Kennzeichen, Norwegen: Fredrikstad"},{"definition":"Kfz-Kennzeichen, Ukraine: Oblast Dnipropetrowsk"}],"synonyms":[],"origins":[],"examples":[{"text":"Nennen Sie mindestens fünf Bedeutungen der Abkürzung AE!","reference":""},{"text":"Der Schlitten mit AE XX-999 bleibt heute beim Blitzmarathon in der Garage.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"AE","id":"15093768e4b0a0"},"0061-0065:7e0ba7dd1a7123":{"word":"Aerogramm","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ae·ro·gramm","de-DE":"Ae·ro·gramm"},"forms":[{"form":"Aerogramm","tags":["Nominativ","Singular"]},{"form":"Aerogramme","tags":["Nominativ","Plural"]},{"form":"Aerogramms","tags":["Genitiv","Singular"]},{"form":"Aerogrammen","tags":["Dativ","Plural"]}],"senses":[{"definition":"postalischer Vordruck, meist in Form eines Briefbogens, der besonders gefaltet wird und zu einem Einheitsporto mit Luftpost transportiert wird"}],"synonyms":[],"origins":["Kompositum aus dem Bestimmungswort „Aero“ von griechisch ἀήρ (aēr), Genitiv: ἀέρος (aeros) – Luft und -gramm von griechisch γράμμα (grámma) ^(→ el) – Brief"],"examples":[{"text":"Das Aerogramm besteht aus einem gefalteten Bogen Briefpapier und darf keine Einlagen enthalten.","reference":""},{"text":"In Deutschland wurden Aerogramme als Form der Postsendung am 01.01.2007 eingestellt.","reference":""}],"idioms":[],"collocations":[],"derivations":["Aerogramm-Papier","Aerogramm-Sammler","Aerogramm-Händler","Original-Aerogramm"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerogramm","id":"7e0ba7dd1a7123"},"0061-0065:910ae41d73c1b1":{"word":"Aerodynamik","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ae·ro·dy·na·mik","de-DE":"Ae·ro·dy·na·mik"},"forms":[{"form":"Aerodynamik","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Wissenschaft, die sich mit der Bewegung von Gasen sowie mit den Kräften beschäftigt, die auf fliegende Körper einwirken"},{"definition":"Verhalten von Körpern bezüglich des Luftwiderstandes"}],"synonyms":[],"origins":["Kompositum aus dem gebundenen Lexem aero- und dem Substantiv Dynamik"],"examples":[{"text":"Gewisse Aspekte der Aerodynamik habe ich noch nicht gänzlich verstanden.","reference":""},{"text":"Die Aerodynamik des Flugzeugs hat nicht zugelassen, dass es noch höher fliegt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerodynamik","id":"910ae41d73c1b1"},"0061-0065:559c7f0a462042":{"word":"Aerobier","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ae·ro·bier","de-DE":"Ae·ro·bier"},"forms":[{"form":"Aerobier","tags":["Nominativ","Singular"]},{"form":"Aerobiern","tags":["Dativ","Plural"]},{"form":"Aerobiers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ein Lebewesen, das ohne Luftsauerstoff nicht überleben kann"}],"synonyms":[],"origins":[],"examples":[{"text":"Fast alle Tiere, die meisten Pilze und viele Bakterien sind obligate Aerobier, d. h., sie haben nur einen Atmungsstoffwechsel mit molekularem Sauerstoff (O₂) (aerobe Atmung).","reference":"Lexikon der Biologie"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerobier","id":"559c7f0a462042"},"0061-0065:bbd5515c56c44d":{"word":"Aerobiont","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ae·ro·bi·ont","de-DE":"Ae·ro·bi·ont"},"forms":[{"form":"Aerobiont","tags":["Nominativ","Singular"]},{"form":"Aerobionten","tags":["Nominativ","Plural"]}],"senses":[{"definition":"ein Lebewesen, das ohne Luftsauerstoff nicht überleben kann"}],"synonyms":[],"origins":[],"examples":[{"text":"„Bei der Atmung der obligaten Aerobionten konnten wir überall Kohlendioxyd, Methan, Wasserstoff*), Schwefelwasserstoff, Ammoniak und Stickstoff in elementarer Form konstatieren.“","reference":"Julius Stoklasa, Josef Pĕnkava: Biologie des Radiums und der radioaktiven Elemente. Band 1: Biologie des Radiums und Uraniums. Verlag von Paul Parey, Berlin 1932. Seite 513"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerobiont","id":"bbd5515c56c44d"},"0061-0065:9795fc3d375fe9":{"word":"Aeolsharfe","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Aeols·har·fe","de-DE":"Aeols·har·fe"},"forms":[{"form":"Äolsharfe","tags":["alternative"]},{"form":"Aeolsharfe","tags":["Nominativ","Singular"]},{"form":"Aeolsharfen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Saiteninstrument, das durch eine Luftströmung erklingt"}],"synonyms":["Geisterharfe","Wetterharfe","Windharfe","Äolsharfe"],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Aeolsharfe","id":"9795fc3d375fe9"},"0061-0065:ceb4db57cf4081":{"word":"Aerosol","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ae·ro·sol","de-DE":"Ae·ro·sol"},"forms":[{"form":"Aerosol","tags":["Nominativ","Singular"]},{"form":"Aerosole","tags":["Nominativ","Plural"]},{"form":"Aerosols","tags":["Genitiv","Singular"]},{"form":"Aerosolen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Gemisch aus fein verteilten flüssigen oder festen Schwebeteilchen und Gasen"}],"synonyms":["Luftpartikel"],"origins":["Neologismus (Neuwort) gebildet aus dem gebundenen Lexem aero-, vom altgriechischen Substantiv ἀήρ (aēr^☆) ^(→ grc) „Luft“, und dem lateinischen Substantiv solutio ^(→ la) „Lösung“"],"examples":[{"text":"Die Auswirkung von Aerosolen auf unsere Umwelt ist noch nicht vollständig geklärt.","reference":""},{"text":"Aerosole befinden sich in der Küchenabluft, also in den aufsteigenden Wrasen und werden durch Aerosolabscheider in der Küchenhaube abgeschieden.","reference":""},{"text":"„Die schwefelhaltigen Aerosole schirmten das Sonnenlicht teilweise ab.“","reference":"Der Tag nach dem Einschlag. In: Spiegel Online. 9. September 2019, ISSN 0038-7452 (URL, abgerufen am 7. Oktober 2019) ."},{"text":"„Doch neben den Tröpfchen, die beim Husten oder Niesen entstehen, und der sogenannten Kontaktinfektion scheint es noch eine dritte Übertragungsform des Virus geben: durch sogenannte Aerosole. Dabei handelt es sich genau genommen auch um Tröpfchen, jedoch beschreiben Aerosole sehr kleine Partikel, die so leicht sind, dass sie lange in der Luft schweben.“","reference":"Wie gefährlich sind Aerosole?, Tagesschau.de. Abgerufen am 18. Mai 2020."}],"idioms":[],"collocations":[],"derivations":["aerosolieren","Aerosolabscheider","Aerosolabscheidung","Aerosolbelastung","Aerosolbombe","Aerosolemission","Aerosolgehalt","Aerosolnebel","Aerosolpartikel"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Aerosol","id":"ceb4db57cf4081"},"0061-0065:f268b6aee4ff3b":{"word":"Aetit","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Aetit","de-DE":"Aetit"},"forms":[{"form":"Aetit","tags":["Nominativ","Singular"]},{"form":"Aetite","tags":["Nominativ","Plural"]},{"form":"Aetits","tags":["Genitiv","Singular"]},{"form":"Aetiten","tags":["Dativ","Plural"]}],"senses":[{"definition":"Mineral, Varietät des hydratisierten Eisenoxids, dem früher magische Kräfte zuerkannt wurden"}],"synonyms":[],"origins":[],"examples":[{"text":"Einst galt der Aetit als Stein, der die Entbindung begünstigt, und wurde daher als Amulett verwendet.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aetit","id":"f268b6aee4ff3b"},"0061-0065:8571746c2b601c":{"word":"Aerinit","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Aer·init","de-DE":"Aer·init"},"forms":[{"form":"Aerinit","tags":["Nominativ","Singular"]},{"form":"Aeriniten","tags":["Nominativ","Plural"]}],"senses":[{"definition":"ein selten vorkommendes Mineral aus der Mineralklasse der „Silikate und Germanate“"}],"synonyms":[],"origins":["abgeleitet von dem altgriechischen Adjektiv ἀέρινος (aerinos^☆) ^(→ grc) (deutsch: himmelblau)"],"examples":[{"text":"Die romanische Wandmalerei des 11. Jahrhunderts in Katalonien verdankt ihre charakteristischen Blautöne Farben, die auf der Basis von Aeriniten hergestellt wurden.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerinit","id":"8571746c2b601c"},"0061-0065:5862f082214152":{"word":"aerifizieren","partOfSpeech":"Verb","gender":"","hyphenation":{"de-CH":"ae·ri·fi·zie·ren","de-DE":"ae·ri·fi·zie·ren"},"forms":[{"form":"haben","tags":["Hilfsverb","Perfekt"]},{"form":"aerifizier!","tags":["Imperativ","Singular"]},{"form":"aerifiziere","tags":["Präsens"]},{"form":"aerifiziert","tags":["Präsens"]},{"form":"aerifiziere!","tags":["Imperativ","Singular"]},{"form":"aerifizieren","tags":["Aktiv","Infinitiv","Präsens"]},{"form":"aerifizierst","tags":["Präsens"]},{"form":"aerifiziert!","tags":["Imperativ","Plural"]},{"form":"aerifizierte","tags":["Präteritum"]},{"form":"aerifizierend","tags":["Partizip","Präsens","Aktiv"]},{"form":"du aerifizierst","tags":["2. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ich aerifiziere","tags":["1. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ihr aerifiziert","tags":["2. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"zu aerifizieren","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"aerifiziert sein","tags":["statal-passive","Infinitiv","Präsens"]},{"form":"du aerifizierest","tags":["2. Person","Singular","Präsens","Aktiv","Konjunktiv I"]},{"form":"ich aerifizierte","tags":["1. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr aerifizieret","tags":["2. Person","Plural","Präsens","Aktiv","Konjunktiv I"]},{"form":"sie aerifizieren","tags":["3. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"wir aerifizieren","tags":["1. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"aerifizieren Sie!","tags":["Imperativ","Höflichkeitsform","Präsens","Aktiv"]},{"form":"aerifiziert haben","tags":["Aktiv","Infinitiv","Perfekt"]},{"form":"du aerifiziertest","tags":["2. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"habe aerifiziert!","tags":["Imperativ","uncommon","2. Person","Singular","Perfekt","Aktiv"]},{"form":"habt aerifiziert!","tags":["Imperativ","uncommon","2. Person","Plural","Perfekt","Aktiv"]},{"form":"ihr aerifiziertet","tags":["2. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"sie aerifizierten","tags":["3. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"wir aerifizierten","tags":["1. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"zu aerifizierende","tags":["Partizip","gerundive"]},{"form":"aerifiziert werden","tags":["Vorgangspassiv","Infinitiv","Präsens"]},{"form":"zu aerifizierender","tags":["Partizip","gerundive"]},{"form":"aerifiziert zu sein","tags":["statal-passive","erweitert","Infinitiv"]},{"form":"du hast aerifiziert","tags":["2. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"aerifiziert zu haben","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"ich habe aerifiziert","tags":["1. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"ihr habt aerifiziert","tags":["2. Person","Plural","Perfekt","Aktiv","Indikativ"]},{"form":"sie sind aerifiziert","tags":["3. Person","Plural","Präsens","statal-passive","Indikativ"]},{"form":"zu aerifizierendes …","tags":["Partizip","gerundive"]},{"form":"aerifiziert zu werden","tags":["Vorgangspassiv","erweitert","Infinitiv"]},{"form":"du habest aerifiziert","tags":["2. Person","Singular","Perfekt","Aktiv","Konjunktiv I"]}],"senses":[{"definition":"mit einem entsprechenden Gerät Löcher in etwas (meist ein Stück Rasen) stechen, damit der Boden gelockert wird"}],"synonyms":[],"origins":["Neuwort aus dem lateinischen Substantiv aer ^(→ la) „Luft“ und dem Verb facere ^(→ la) „machen“"],"examples":[{"text":"„Der Rasen braucht Sonne, Wasser und Dünger. Und er muss aerifiziert werden, ein Vorgang, bei dem normalerweise eine kleine Walze Löcher in das Gras stößt, damit der Rasen atmen kann.“","reference":"Rainer Schäfer: Die Düngergrätsche. In: Zeit Online. 22. Juni 2007, ISSN 0044-2070 (URL, abgerufen am 14. Mai 2012) ."}],"idioms":[],"collocations":[],"derivations":["Aerifizieren","aerifizierend","aerifiziert"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"aerifizieren","id":"5862f082214152"},"0061-0065:0a3c1a49269321":{"word":"Aeroklub","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ae·ro·klub","de-DE":"Ae·ro·klub"},"forms":[{"form":"Aeroclub","tags":["alternative"]},{"form":"Aeroklub","tags":["Nominativ","Singular"]},{"form":"Aeroklubs","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Verein für Flugsport, insbesondere für Sportflieger, Segelflieger und Fallschirmspringer"}],"synonyms":[],"origins":[],"examples":[{"text":"„Modellflugzeuge hatte er schon früher gebastelt, jetzt trat er dem Aeroklub bei und nahm Flugunterricht.“","reference":"Theo Sommer: „Ich wollte immer Kosmonaut werden“. In: Zeit Online. Nummer 17, 21. April 1961, ISSN 0044-2070 (URL, abgerufen am 14. Mai 2012) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aeroklub","id":"0a3c1a49269321"},"0061-0065:db84f521d8ff2c":{"word":"Aeroclub","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ae·ro·club","de-DE":"Ae·ro·club"},"forms":[{"form":"Aeroclub","tags":["Nominativ","Singular"]},{"form":"Aeroklub","tags":["alternative"]},{"form":"Aeroclubs","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Verein für Flugsport, insbesondere für Sportflieger, Segelflieger und Fallschirmspringer"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die meisten der rund zwölf Modelle, mit denen gegenwärtig in England, Japan und Österreich an technischen Hochschulen und in Aeroclubs das Muskelfliegen betrieben wird, sind Kombinationen von einem Segelflugzeug mit einem Fahrrad.“","reference":"Zum Fliegen wenig tauglich. In: Zeit Online. Nummer 5, 26. Januar 1973, ISSN 0044-2070 (URL, abgerufen am 14. Mai 2012) ."},{"text":"„Der Aeroclub Hoyerswerda hat seit einiger Zeit auch eine Sektion Gleitschirmfliegen. Auch mitten im platten Flachland wird diese Trend-Luftsportart also betrieben.“","reference":"Katrin Würz: Gleitschirmflieger wollen für ihren Sport werben. Abgerufen am 14. März 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aeroclub","id":"db84f521d8ff2c"},"0061-0065:b377b3e4622b27":{"word":"aero-","partOfSpeech":"Gebundenes Lexem","gender":"","hyphenation":{"de-CH":"aero-","de-DE":"aero-"},"forms":[{"form":"aer-","tags":["variant"]}],"senses":[{"definition":"Luft, zur Luft gehörend"}],"synonyms":[],"origins":["von griechisch ἀήρ (aēr^☆) ^(→ grc) „Luft“, erweitert um das Fugenelement -o-"],"examples":[{"text":"Aerodrom ist ein anderes Wort für einen Flugplatz oder Flughafen.","reference":""}],"idioms":[],"collocations":[],"derivations":["aerodynamisch","aerogen","aerotherm","Aerobiologie","Aerobiont","Aerobiose","Aerobus","Aeroclub","Aerodrom","Aerodynamik","Aeroelastizität","Aerophon","Aerofotografie","Aerophotogrammmetrie","Aerogeologie","Aerogeophysik","Aerogramm","Aeroklub","Aerolith","Aerologie","Aeromechanik","Aeromedizin","Aerometer","Aeronaut","Aeronautik","Aeronomie","Aeropause","Aerophobie","Aeroplan","Aerosalon","Aerosol","Aerosonde","Aerostatik","Aerotaxi","Aerotherapie","Aerotrain"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"aero-","id":"b377b3e4622b27"},"0061-0065:c2d782f1b94ca1":{"word":"Aeroplan","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Aero·plan","de-DE":"Aero·plan"},"forms":[{"form":"Aeroplan","tags":["Nominativ","Singular"]},{"form":"Aeroplane","tags":["Nominativ","Plural"]},{"form":"Aeroplans","tags":["Genitiv","Singular"]},{"form":"Aeroplanen","tags":["Dativ","Plural"]},{"form":"Aeroplanes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Flugzeug"}],"synonyms":["Flieger","Flugzeug","Kiste","Maschine","Vogel"],"origins":["Ende des 19. Jahrhunderts vermutlich von französisch aéroplane ^(→ fr) entlehnt; voraus geht griechisch ἀερόπλανος (aeroplanos^☆) ^(→ grc) „in der Luft umherschweifend“"],"examples":[{"text":"„Fabian hatte mit einem Male die Vorstellung, er fliege dort oben im Aeroplan und sehe auf sich hinunter, auf den jungen Mann in der Joachimstaler Straße, im Gewimmel der Menge, im Lichtkreis der Laternen und Schaufenster, im Straßengewirr der fiebrig entzündeten Nacht.“","reference":"Erich Kästner: Fabian. In: Kästner für Erwachsene 3. Deutscher Bücherbund, Stuttgart/München ohne Jahr, Seite 7-201, Zitat Seite 13 f. Erstdruck 1931."},{"text":"„Über der Stadt kreisen Aeroplane und werfen Flugzettel herab.“","reference":"Ernst Toller: Eine Jugend in Deutschland. Reclam, Stuttgart 2013, ISBN 978-3-15-018688-6 , Seite 174. Erstauflage 1933."},{"text":"„Die Aeroplane, französische und solche mit dem Eisernen Kreuz, hängen als winziges Kinderspielzeug auf Drähten, sie, die wir riesenhaft über den Kolonnen schwirren sahen.“","reference":"Egon Erwin Kisch: Paradies Amerika. Axel Springer, Berlin 2013, ISBN 978-3-942656-71-9, Seite 135f ; Erstdruck 1930."},{"text":"„Aber das war ja auch wirklich welterschütternd und sprengte alle Rahmen vorstellbarer Situationen, wenn beim ›Prinz-Heinrich-Flug‹ im Jahr 1912, an dem sich alle Piloten des Reichs beteiligten und der von Ort zu Ort über ganz Deutschland ging, mehr als hundert Aeroplane, gebrechliche, feindrahtige Gestelle, Euler-Doppeldecker und Eindecker-Tauben, in langen Abständen auf dem ›Großen Sand‹ zwischenlandeten, und man saß mit der Uhr in der Hand neben Goedeckers Morse-Apparat und stoppte mit: wer ist wo aufgestiegen, wer ist wo abgestürzt, wer ist noch in der Luft!“","reference":"Carl Zuckmayer: Als wär's ein Stück von mir. Horen der Freundschaft. S. Fischer, (Frankfurt/Main) 1994, ISBN 3-10-396502-8, Seite 206."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Aeroplan","id":"c2d782f1b94ca1"},"0061-0065:52e0d6346e2a62":{"word":"Aerosolabscheider","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ae·ro·so·l·ab·schei·der","de-DE":"Ae·ro·so·l·ab·schei·der"},"forms":[{"form":"Aerosolabscheider","tags":["Nominativ","Singular"]},{"form":"Aerosolabscheidern","tags":["Dativ","Plural"]},{"form":"Aerosolabscheiders","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Vorrichtung zum Abscheiden von feinst verteilten, schwebenden festen oder flüssigen Stoffen aus Luft, Gasen oder Dämpfen"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Aerosol und Abscheider"],"examples":[{"text":"„Ein Aerosolabscheider ist dementsprechend eine Anlage der Luftreinigungstechnik. Ein Aerosolabscheider ist dafür zuständig, aus einem Aerosol gefährliche oder umweltschädigende Dispersionen auszuleiten und ihrer korrekten Entsorgung zuzuführen.“","reference":"Aerosolabscheider''www.aerosolabscheider.net, abgerufen am 27. August 2013"},{"text":"„Bevor die Abluft einer Küche in die Abluftleitungen strömt, muss sie zuvor durch hochwirksame Aerosolabscheider (früher Fettfanggitter) gereinigt werden.“","reference":"Grundlagen der Küchenlüftungwww.ikz.de, abgerufen am 27. August 2013"},{"text":"„Der mechanische Aerosolabscheider dient dazu, große Aerosolpartikel aus dem Abluftstrom zu entfernen und fungiert außerdem als Brandschutz, indem er Flammen aus dem Abluft- und Kanalbereich der Haube fernhält.“","reference":"Zyklonische Aerosolabscheidungwww.halton.de, abgerufen am 27. August 2013"},{"text":"„Diese Norm beinhaltet Anforderungen an die Bau- und Betriebsweise von Aerosolabscheidern, die in Küchenlüftungshauben und -decken für den Gebrauch in gewerbsmäßigen Küchen integriert sind, einschließlich der Prüfungen des Flammdurchschlags, der technischen Sicherheit und hygienischen Merkmale.“","reference":"Flammschutzfilter (Aerosolabscheider)nach DIN 18869-5 & VDI 2052(PDF; 38KB), www.walpol.de, abgerufen am 27.August 2013"},{"text":"„Seit in der VDI 2052 erstmals definiert wurde, wie Abscheidegrade von Aerosolabscheidern (früher Fettabscheider bzw. Filter genannt) zu messen und anzugeben sind, ist die Entwicklung zu hochwertigen Abscheidern rasant fortgeschritten.“","reference":"Küchenlüftungsdecken - Aerosolabscheider''www.kuechenlueftung.at, abgerufen am 27. August"},{"text":"„Die Ergebnisse bildeten die Grundlage für die anschließende Optimierung von Aerosolabscheidern sowie eine komplette Neukonstruktion eines Aerosolabscheiders für nicht wassermischbare Kühlschmierstoffe.“","reference":"Entwicklung optimierter Aerosolabscheider für den Einsatz in der Abluft von Metallbearbeitungsprozessen www.dbu.de, abgerufen am 3. August 2014"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerosolabscheider","id":"52e0d6346e2a62"},"0061-0065:859954753e91a2":{"word":"Aerophilatelie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Aero·phil·ate·lie","de-DE":"Aero·phil·ate·lie"},"forms":[{"form":"Aerophilatelie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Spezialgebiet der Philatelie, das sich mit der Flugpost/Luftpost befasst"}],"synonyms":[],"origins":["Determinativkompositum aus aero- und Philatelie"],"examples":[{"text":"„Diese Belege zählen zu den begehrtesten Sammlerstücken der Aerophilatelie.“","reference":"Deutsche Post (Herausgeber): Brieftauben, Ballone, Blechkanister. Postbeförderung zwischen Innovation und Kuriosität. ohne Verlagsangabe, ohne Ortsangabe 2013 , Seite 56."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerophilatelie","id":"859954753e91a2"},"0061-0065:446d416f9e5d33":{"word":"Aerolith","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Aer·o·lith","de-DE":"Aer·o·lith"},"forms":[{"form":"Aerolith","tags":["Nominativ","Singular"]},{"form":"Aerolithe","tags":["Nominativ","Plural"]},{"form":"Aeroliths","tags":["Genitiv","Singular"]},{"form":"Aerolithen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Meteorit"}],"synonyms":[],"origins":[],"examples":[{"text":"„Was das Material ist, aus dem der schwarze Stein besteht, das ist bei der Decke von Schmutz und Fett, die ihn umgibt, schwer zu sagen. Der Reisende Burckardt hat ihn für ein Stück Lava erklärt, Burton dagegen behauptet, überzeugt zu sein, daß er ein Aerolith oder Luftstein sei.“","reference":"August Wilhelm Grube: Asien und Australien. In: Projekt Gutenberg-DE. Dritter Abschnitte. Arabien. Mekka und die Kaaba. (URL) . Alte Version im Internet-Archiv abrufbar. *"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerolith","id":"446d416f9e5d33"},"0061-0065:517ea628a9bd69":{"word":"Aeromantie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ae·ro·man·tie","de-DE":"Ae·ro·man·tie"},"forms":[{"form":"Aeromantie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Wahrsagung durch Beobachtung und Deutung von Himmelsphänomenen oder atmosphärischen Bedingungen"}],"synonyms":[],"origins":["von griechisch ἀήρ (aēr^☆) ^(→ grc) „Luft“ und μαντεία (manteia^☆) ^(→ grc) „Weissagung“"],"examples":[{"text":"„Da die mittelalterliche Definition der Elementedivinationen sich im Wesentlichen an die Antike anschließt, herrscht auch hier noch eine gewisse Unsicherheit, die noch dadurch verstärkt wird, dass bei der Aeromantie die Beteiligung dämonischer Kräfte angenommen wurde.“","reference":"Christa Agnes Tuczay: Kulturgeschichte der mittelalterlichen Wahrsagerei. Kapitel V. Mittelalterliche mantische Einzelkünste. De Gruyter 2012, S. 136"},{"text":"„Und wahrscheinlich hat auch der Umstand, dass man aus der Beschaffenheit der Luft (Schwere, Leichtigkeit, Wärme, Kälte, Trockenheit, Feuchtigkeit, etc.) zum Theile die Witterung vorausbestimmen kann, Anlaß zur Aeromantie gegeben; […]“","reference":"Wilhelm Traugott Krug: Encyklopädisches Lexikon in Bezug auf die neueste Literatur und Geschichte der Philosophie: A - L, Band 1. Brockhaus 1838, S. 31"}],"idioms":[],"collocations":[],"derivations":["Aeromant"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aeromantie","id":"517ea628a9bd69"},"0061-0065:498331f6ff0c62":{"word":"Aerosolbombe","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ae·ro·sol·bom·be","de-DE":"Ae·ro·sol·bom·be"},"forms":[{"form":"Aerosolbombe","tags":["Nominativ","Singular"]},{"form":"Aerosolbomben","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Bombe, deren Wirkung auf der Freisetzung und der anschließenden Zündung eines Aerosols beruht"}],"synonyms":["Druckluftbombe","Vakuumbombe"],"origins":["Determinativkompositum aus den Substantiven Aerosol und Bombe"],"examples":[{"text":"„Eliot Higgins kennt den Unterschied zwischen einem Granatwerfer des Typs Milkor MGL und des Typs RBG-6, und er weiß, dass eine Aerosolbombe keine chemischen Kampfstoffe enthält.“","reference":"Der YouTube-Waffenexperte. Abgerufen am 9. Dezember 2021."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Aerosolbombe","id":"498331f6ff0c62"},"0061-0065:bffb004f54edb4":{"word":"Aerodrom","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ae·ro·drom","de-DE":"Ae·ro·drom"},"forms":[{"form":"Aerodrom","tags":["Nominativ","Singular"]},{"form":"Aerodrome","tags":["Nominativ","Plural"]},{"form":"Aerodroms","tags":["Genitiv","Singular"]},{"form":"Aerodromen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Areal, auf dem Flugzeuge starten und wieder landen"},{"definition":"Luftschiff, Flugobjekt"}],"synonyms":["Airport","Flugfeld","Flughafen","Flugplatz","Lufthafen","Luftverkehrszentrum","Sonderlandeplatz","Verkehrsflughafen","Verkehrslandeplatz"],"origins":[],"examples":[{"text":"„Wir sind angekommen. Vor dem Aerodrom liegt noch ein großer Platz mit verdächtigen Holzhäuschen, für die wir andere Aufschriften erwartet hätten, als: Garage, Grand Büfett International und so weiter.“","reference":"Franz Kafka: Die Aeroplane in Brescia. Abgerufen am 5. Juni 2017."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Aerodrom","id":"bffb004f54edb4"},"0061-0065:73263d9f596f99":{"word":"AEMR","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"AEMR","de-DE":"AEMR"},"forms":[],"senses":[{"definition":"Allgemeine Erklärung der Menschenrechte"}],"synonyms":[],"origins":[],"examples":[{"text":"Die AEMR bildet die Grundlage für den internationalen Menschenrechtsschutz und enthält bereits die zentralen politischen, bürgerlichen, wirtschaftlichen, sozialen und kulturellen Menschenrechte.","reference":"Allgemeine Erklärung der Menschenrechte. Abgerufen am 9. März 2018."},{"text":"Diese wurden seit der Verabschiedung der AEMR im Jahr 1948 kontinuierlich präzisiert und in zahlreichen Konventionen und Resolutionen völkerrechtlich bindend verankert.","reference":""},{"text":"Die Allgemeine Erklärung der Menschenrechte (AEMR) nahm nicht nur zahlreiche Inhalte staatlicher Grundrechte auf.","reference":"1948 – Internationale Menschenrechte für die Republik. Bundeskanzleramt (AT), abgerufen am 9. März 2018."},{"text":"Als besonders bedeutsam ist die in Artikel 21 AEMR zum Ausdruck gebrachte Verbindung der Menschrechtsidee mit der Staatsform der Demokratie hervorzuheben.","reference":""},{"text":"Einen Bestandsschutz der in der AEMR aufgeführten Rechte bietet Art. 30 AEMR. Danach darf sich kein Individuum, Gruppe oder Staat auf ein darin verbürgtes Recht oder Freiheit berufen, um ein anderes in der AEMR enthaltenes Recht und Freiheit zu beseitigen (AEMR 1948: 189).","reference":"Jan-Philipp Sommer: Normen als Grund bilateraler Außenpolitik. Die deutsche Außenpolitik gegenüber Polen am Anfang des 21. Jahrhunderts. Springer-Verlag, 2015, ISBN 9783658101244, Seite 145 (zitiert nach Google Books) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"AEMR","id":"73263d9f596f99"},"0061-0065:29ec034a8afd1d":{"word":"Aeronaut","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ae·ro·naut","de-DE":"Ae·ro·naut"},"forms":[{"form":"Aeronaut","tags":["Nominativ","Singular"]},{"form":"Aeronauten","tags":["Nominativ","Plural"]},{"form":"Aeronautin","tags":["feminine"]}],"senses":[{"definition":"jemand, der ein Luftschiff oder einen Heißluftballon betreibt beziehungsweise damit fliegt; Flieger, Luftfahrer"}],"synonyms":[],"origins":[],"examples":[{"text":"Er ist ein wahrer Aeronaut. Er hat tausende Kilometer in seinem Leben zurückgelegt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aeronaut","id":"29ec034a8afd1d"},"0061-0065:ed86ec03b2126f":{"word":"Aeronautin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ae·ro·nau·tin","de-DE":"Ae·ro·nau·tin"},"forms":[{"form":"Aeronaut","tags":["masculine"]},{"form":"Aeronautin","tags":["Nominativ","Singular"]},{"form":"Aeronautinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Luftfahrerin, Luftschifferin"}],"synonyms":[],"origins":[],"examples":[{"text":"Sie ist eine wahre Aeronautin. Sie hat tausende Kilometer in ihrem Leben zurückgelegt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aeronautin","id":"ed86ec03b2126f"},"0061-0065:d40bf9bef1bb3a":{"word":"Aetosaurus","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ae·to·sau·rus","de-DE":"Ae·to·sau·rus"},"forms":[{"form":"Aetosaurus","tags":["Nominativ","Singular"]},{"form":"Aetosaurier","tags":["variant"]},{"form":"Aetosauriern","tags":["Dativ","Plural"]}],"senses":[{"definition":"mittelgroßer, pflanzenfressender Saurier, der in der späten Trias lebte"}],"synonyms":[],"origins":[],"examples":[{"text":"Wir wurden eingeladen, eine verkleinerte plastische Nachbildung von Aetosaurus zu bewundern.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aetosaurus","id":"d40bf9bef1bb3a"},"0061-0065:7d1cd27e95ed9a":{"word":"Aedil","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Aedil","de-DE":"Aedil"},"forms":[{"form":"Ädil","tags":["alternative"]},{"form":"Aedil","tags":["Nominativ","Singular"]},{"form":"Aedils","tags":["Genitiv","Singular"]},{"form":"Aedilen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"niedriges Amt in der römischen Ämterlaufbahn, hauptsächlich Polizeibeamter, aber der Aufgabenbereich unterlag über die Jahrhunderte einem Wandel"}],"synonyms":[],"origins":[],"examples":[{"text":"„Im Jahr 33 v. Chr. wird er ins Amt des Aedilen gewählt, der für die Stadtentwicklung zuständig ist.“","reference":"Volker Michael Strocka: Die ewige Baustelle. In: Zeit Geschichte. Epochen. Menschen. Ideen. Nummer 2, 2014, Seite 67."},{"text":"„33 v. Chr. lässt Agrippa sich zum Aedilen wählen.“","reference":"Marike Frick: Der zweite Mann im Staat. In: Zeit Geschichte. Epochen. Menschen. Ideen. Nummer 2, 2014, Seite 59."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aedil","id":"7d1cd27e95ed9a"},"0061-0065:9bba1f3800194a":{"word":"Aerometer","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ae·ro·me·ter","de-DE":"Ae·ro·me·ter"},"forms":[{"form":"Aerometer","tags":["Nominativ","Singular"]},{"form":"Aerometern","tags":["Dativ","Plural"]},{"form":"Aerometers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Messgerät zum Bestimmen unterschiedlicher Eigenschaften von Gasen"}],"synonyms":["Ärometer"],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Aerometer","id":"9bba1f3800194a"},"0061-0065:e1f9e1a2ffdfa7":{"word":"Aerologie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ae·ro·lo·gie","de-DE":"Ae·ro·lo·gie"},"forms":[{"form":"Aerologie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Wissenschaft, die sich mit der Erforschung der oberen Luftschichten der Atmosphäre befasst, die nicht von den Bodenschichten beeinflusst sind"}],"synonyms":["Höhenwetterkunde"],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":["aerologisch"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Aerologie","id":"e1f9e1a2ffdfa7"},"0061-0065:d419066431bd4b":{"word":"Aegipan","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Aegi·pan","de-DE":"Aegi·pan"},"forms":[{"form":"Ägipan","tags":["alternative"]},{"form":"Aegipan","tags":["Nominativ","Singular"]},{"form":"Aegipane","tags":["Nominativ","Plural"]},{"form":"Aegipans","tags":["Genitiv","Singular"]},{"form":"Aegipanen","tags":["Dativ","Plural"]},{"form":"Aegipanes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Waldgott mit Ziegenfüßen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Ziegen hüpften zum Klang kleiner, verfluchter Flöten, und Aegipane jagten missgestaltete Faune unaufhörlich über Felsen hinweg, die aussahen wie angeschwollene Kröten.“","reference":"H.P. Lovecraft: Das Grauen in Red Hook. In: Das Gesamtwerk: Sämtliche Erzählungen und Zusammenarbeiten. Festa, Leipzig 2020, ISBN 978-3-865-52882-7, Seite 533 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aegipan","id":"d419066431bd4b"},"0061-0065:ab35266e4b6abc":{"word":"Aerobus","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ae·ro·bus","de-DE":"Ae·ro·bus"},"forms":[{"form":"Aerobus","tags":["Nominativ","Singular"]},{"form":"Aerobusse","tags":["Nominativ","Plural"]},{"form":"Aerobussen","tags":["Dativ","Plural"]},{"form":"Aerobusses","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Hubschrauber im Taxidienst"},{"definition":"aus einer Kabine bestehendes Nahverkehrsmittel, das an Kabeln zwischen Masten schwebt"}],"synonyms":[],"origins":["Determinativkompositum aus dem Substantiv Bus mit dem gebundenen Lexem Aero-"],"examples":[{"text":"„Sollte es tatsächlich zum Bau der Einbahnschiene kommen, steht auch schon das nächste Megaprojekt an: ein ‚Aerobus‘ soll Touristen bequem auf die Insel Koh Larn bringen.“","reference":"Drei Tote und Hunderte Verletzte bei übertriebener Gewaltanwendung gegen Demonstranten. In: Pattaya Blatt. Abgerufen am 8. August 2024."},{"text":"„Der Aerobus verkehrt als Shuttle zwischen dem Flughafen und der Innenstadt.“","reference":"Wikivoyage-Eintrag „Lissabon“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aerobus","id":"ab35266e4b6abc"},"0061-0065:f92647d1bca2f9":{"word":"ae-Ligatur","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"ae-Li·ga·tur","de-DE":"ae-Li·ga·tur"},"forms":[{"form":"ae-Ligatur","tags":["Nominativ","Singular"]},{"form":"ae-Ligaturen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"zu einem Schriftzeichen verbundene Buchstaben a und e – æ"}],"synonyms":[],"origins":[],"examples":[{"text":"„Eine eigenartige Schreibung des akzentuierten ê ist in einigen süddeutschen […] Handschriften zu beobachten […]: der Zirkumflex wird nicht über den Buchstaben gesetzt, sondern unter der Zeile an ihn angehängt als e-caudata (ę) wie sie in anderer Bedeutung in lateinischen Codices seit dem 10./11. Jahrhundert die ältere ae-Ligatur ersetzte.“","reference":"Karin Schneider: Akzentuierung in mittelalterlichen deutschsprachigen Handschriften. In: Edition und Sprachgeschichte. Baseler Fachtagung 2.–4. März 2005. de Gruyter, 2012, ISBN 978-3-11-093886-9, Seite 23 (Zitiert nach Google Books)"},{"text":"„Der Zirkumflex sowie die ae-Ligatur hingegen können übernommen werden.“","reference":"Margarete Springeth: Der analytische Weg ist das Ziel. Die mittelhochdeutsche Begriffsdatenbank als Online-Textarchiv Sammelwerk=Wege zum Text. de Gruyter, 2009, ISBN 978-3-484-29530-8, Seite 190 (Zitiert nach Google Books)"},{"text":"„In zunehmendem Maße begegnet in den Hss. […] ein e mit einem diakritischen Zeichen (cauda), welches nichts anderes ist als das Rudiment des a in einer fmal. ae-Ligatur: ę o. ä.“","reference":"Peter Stotz: Handbuch zur lateinischen Sprache des Mittelalters. Dritter Band – Lautlehre. Beck, 1996, ISBN 978-3-406-40362-0, Seite 82 (Zitiert nach Google Books)"},{"text":"„Regelmäßig schreibt er das offene e als ae-Ligatur (Aenmaerkingen).“","reference":"Wilfried Schöntag: Die Marchtaler Fälschungen. Das Prämonstratenserstift Marchtal im politischen Kräftespiel (1171–1312). de Gruyter, 2017, ISBN 978-3-11-046738-3, Seite 10 (Zitiert nach Google Books)"},{"text":"„In dieser Ligatur ist eine ganz natürliche und gewohnte Linienführung unterbrochen und vielleicht unter dem Einfluß und nach dem Vorbild der häufigen ae-Ligatur umgestaltet, was beim Schreiben Aufgabe eines Vorteils bedeutet.“","reference":"Bernhard Bischoff: Die Sudostdeutschen Schreibschulen und Bibliotheken in der Karolongerzeit. Teil 1 – Die bayrischen Diözesen. Harrassowitz, 1974, ISBN 978-3-447-00215-8, Seite 249 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ae-Ligatur","id":"f92647d1bca2f9"},"0061-0065:ece40d1a94ba8f":{"word":"Aenne","partOfSpeech":"Vorname","gender":"die","hyphenation":{"de-CH":"Aen·ne","de-DE":"Aen·ne"},"forms":[{"form":"A.","tags":["Kurzform"]},{"form":"Anja","tags":["variant"]},{"form":"Anna","tags":["variant"]},{"form":"Anne","tags":["variant"]},{"form":"Änne","tags":["alternative"]},{"form":"Änni","tags":["variant"]},{"form":"Aenne","tags":["Nominativ","Singular"]},{"form":"Aenni","tags":["variant"]},{"form":"Andel","tags":["variant"]},{"form":"Annie","tags":["variant"]},{"form":"Aennes","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weiblicher Vorname"}],"synonyms":[],"origins":["[1] Nebenform von Anna"],"examples":[{"text":"Aenne spielt sehr gut Tennis.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aenne","id":"ece40d1a94ba8f"},"0061-0065:eb7730da5e5afc":{"word":"Aeschenplatz","partOfSpeech":"Straßenname","gender":"der","hyphenation":{"de-CH":"Aeschen·platz","de-DE":"Aeschen·platz"},"forms":[{"form":"Aeschenplatz","tags":["Nominativ","Singular"]},{"form":"Aeschenplatzes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Platz im Zentrum von Basel"}],"synonyms":[],"origins":["[1] Der im 19. Jahrhundert gebaute Aeschenplatz hat seinen Namen nach dem einstigen mittelalterlichen Aeschentor. 1279 ist das Stadttor erstmals als Eschemertor bezeugt, 1288 als Eschmartor."],"examples":[{"text":"„Offenbar arbeitete Brigitte Sondermann mit dem übrigen IT-Team in der zweiten Niederlassung der BIZ, einem weißen Rundbau am Aeschenplatz, wenige hundert Meter vom Hilton entfernt.“","reference":"David Ignatius: Ein neuer Feind. Rowohlt, Reinbek bei Hamburg 2016, ISBN 978-3-499-27094-9, Seite 180 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aeschenplatz","id":"eb7730da5e5afc"},"0061-0065:9e390377d2ea55":{"word":"Aeschlimann","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Aeschli·mann","de-DE":"Aeschli·mann"},"forms":[{"form":"A.","tags":["Kurzform"]},{"form":"Äschlimann","tags":["alternative"]},{"form":"Aeschlimann","tags":["Nominativ","Singular","masculine"]},{"form":"Aeschlimanns","tags":["Genitiv","Singular","masculine"]},{"form":"dem Aeschlimann","tags":["Dativ","Singular","masculine"]},{"form":"den Aeschlimann","tags":["Akkusativ","Singular","masculine"]},{"form":"der Aeschlimann","tags":["Nominativ","Singular","masculine"]},{"form":"des Aeschlimann","tags":["Genitiv","Singular","masculine"]},{"form":"die Aeschlimann","tags":["Nominativ","Singular","feminine"]},{"form":"den Aeschlimanns","tags":["Dativ","Plural"]},{"form":"der Aeschlimanns","tags":["Genitiv","Plural"]},{"form":"des Aeschlimanns","tags":["Genitiv","Singular","masculine"]},{"form":"die Aeschlimanns","tags":["Nominativ","Plural"]}],"senses":[{"definition":"deutschsprachiger Nachname, Familienname"}],"synonyms":[],"origins":[],"examples":[{"text":"Frau Aeschlimann arbeitet als Edelsteinschleiferin.","reference":""},{"text":"Herr Aeschlimann spaziert gerne durch die Wälder.","reference":""},{"text":"Die Aeschlimanns fliegen heute nach Eilat.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Aeschlimann","id":"9e390377d2ea55"}};
